<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useApplication} from '../../application';import OperationsRecovery from '../governance/OperationsRecovery.vue';import type {MailContext,MailJob} from '../governance/operations-types';
const {session,operationsCommands:ops}=useApplication(),dialog=ref<HTMLDialogElement>(),meeting=ref(''),context=ref<MailContext|null>(null),selected=ref<string[]>([]),jobs=ref<MailJob[]>([]),loading=ref(false),error=ref(''),message=ref('');let epoch=0;
const busy=computed(()=>loading.value||ops.command.state.value==='SENDING');
async function reload(){const id=meeting.value,turn=epoch;if(!id)return;loading.value=true;error.value='';try{const [c,h]=await Promise.allSettled([ops.read<MailContext>(`/api/v1/meetings/${id}/mail-context`),ops.read<MailJob[]>(`/api/v1/meetings/${id}/mail`)]);if(turn!==epoch||id!==meeting.value)return;if(!ops.available.value){conceal();return;}context.value=c.status==='fulfilled'?c.value:null;jobs.value=h.status==='fulfilled'?h.value:[];selected.value=selected.value.filter(person=>context.value?.recipients.some(p=>p.enterpriseId===person));if(c.status==='rejected')error.value='当前来源暂不可用于发送，可继续查看本人发送记录。';if(h.status==='rejected')error.value='发送记录当前不可读取，请重新核对当前账号。';}finally{if(turn===epoch)loading.value=false;}}
async function open(id:string){conceal();meeting.value=id;dialog.value?.showModal();await reload();}
function conceal(){epoch++;dialog.value?.close();meeting.value='';context.value=null;jobs.value=[];selected.value=[];error.value='';message.value='';loading.value=false;}
async function send(){const id=meeting.value,c=context.value,turn=epoch;if(!c||!selected.value.length||busy.value||ops.pending.value)return;loading.value=true;error.value='';try{await ops.submit(`/api/v1/meetings/${id}/mail`,{sourceRevisionToken:c.sourceRevisionToken,publicationId:c.publicationId,recipientEnterpriseIds:[...selected.value]});if(turn===epoch){message.value='发送任务已受理。投递未知时仅查询原业务键，不自动重发。';await reload();}}catch(cause){if(turn===epoch)error.value=cause instanceof Error?cause.message:'请保留原请求并查回结果。';}finally{if(turn===epoch)loading.value=false;}}
const stop=watch(()=>session.current.value?.actor.enterpriseId,conceal,{flush:'sync'});watch(()=>ops.available.value,available=>{if(!available)conceal();},{flush:'sync'});watch(()=>ops.pending.value,(pending,was)=>{if(was&&!pending&&meeting.value)void reload();});onUnmounted(()=>{stop();conceal();});defineExpose({open,close:conceal});
const states={PENDING:'等待发送',UNKNOWN:'投递结果待查询',SENT:'已发送',FAILED:'发送失败',BLOCKED:'权限或版本已失效'};
</script>
<template><dialog ref="dialog" class="ops-mail-dialog" aria-label="发送纪要邮件" @cancel="conceal"><div class="modal-head"><h2>发送纪要邮件</h2><button class="btn ghost" aria-label="关闭纪要邮件" @click="conceal">×</button></div><div class="ops-mail-content"><p class="banner info">向当前获授权的企业人员发送纪要查看链接。邮件不包含正文或附件，打开链接仍须登录并通过权限检查。</p><OperationsRecovery/><p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="message" class="banner success" role="status">{{message}}</p><p v-if="loading" role="status">正在核对权限与邮件记录…</p><fieldset v-if="context" :disabled="busy||ops.pending.value"><legend>选择收件人（最多20人）</legend><label v-for="p in context.recipients" :key="p.enterpriseId"><input v-model="selected" type="checkbox" :value="p.enterpriseId" :disabled="selected.length>=20&&!selected.includes(p.enterpriseId)"/>{{p.displayName}} <span class="muted">{{p.enterpriseId}}</span></label></fieldset><h3>发送记录</h3><div v-for="job in jobs" :key="job.id" class="ops-mail-record"><b>{{states[job.state]}}</b> · {{job.createdAt}}<p v-if="job.lastError" class="muted">{{job.lastError}}</p><span class="small muted">{{job.id}}</span></div><p v-if="!jobs.length&&!loading" class="muted">暂无发送记录</p></div><div class="modal-foot"><button class="btn" @click="conceal">关闭</button><button class="btn" :disabled="busy" @click="reload">查询发送结果</button><button class="btn primary" :disabled="busy||ops.pending.value||!context||!selected.length" @click="send">发送受控链接</button></div></dialog></template>
<style scoped>.ops-mail-dialog{width:680px;max-width:calc(100vw - 48px);padding:0;border:0;border-radius:12px;max-height:85vh}.ops-mail-dialog::backdrop{background:rgba(15,23,42,.35)}.modal-head,.modal-foot{display:flex;align-items:center;gap:12px;padding:18px 24px;border-bottom:1px solid var(--border)}.modal-head h2{font-size:18px;flex:1;margin:0}.modal-foot{justify-content:flex-end;border-top:1px solid var(--border);border-bottom:0}.ops-mail-content{padding:20px 24px;max-height:60vh;overflow:auto}.ops-mail-content fieldset{border:1px solid var(--border);border-radius:8px;padding:16px}.ops-mail-content label{display:flex;align-items:center;gap:8px;margin:10px 0}.ops-mail-record{border-top:1px solid var(--border);padding:12px 0;overflow-wrap:anywhere}.ops-mail-content .banner{line-height:1.7}</style>
